def addBoldTag(s, words):
    n = len(s)
    is_bold = [False] * n  # Boolean mask for bold positions

    # Mark all locations that need to be bolded
    for word in words:
        start = s.find(word)
        while start != -1:
            for i in range(start, start + len(word)):
                is_bold[i] = True
            start = s.find(word, start + 1)

    res = []
    i = 0
    while i < n:
        if is_bold[i]:
            res.append('<b>')
            while i < n and is_bold[i]:
                res.append(s[i])
                i += 1
            res.append('</b>')
        else:
            res.append(s[i])
            i += 1

    return ''.join(res)
